package com.codepathacademy.learning;
import com.codepathacademy.identity.AppUser;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity @Table(name="local_data_imports") class LearningDataImport { @Id @GeneratedValue private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="user_id")private AppUser user;@JdbcTypeCode(SqlTypes.CHAR)@Column(columnDefinition="char(64)")private String fingerprint;@Column(name="import_key")private String importKey;private String status;@JdbcTypeCode(SqlTypes.JSON)@Column(columnDefinition="jsonb")private String summary;@Column(name="imported_at")private Instant importedAt=Instant.now();@Column(name="completed_at")private Instant completedAt;protected LearningDataImport(){}LearningDataImport(AppUser user,String fingerprint,String key,String summary){this.user=user;this.fingerprint=fingerprint;importKey=key;this.summary=summary;status="COMPLETED";completedAt=Instant.now();}UUID getId(){return id;}String getFingerprint(){return fingerprint;}String getSummary(){return summary;}}
